mapper.select:
select t.* from( select ROW_NUMBER() OVER(order by sal_pymnt_date desc) RNUM, s.*, e.position_no, u.user_nm,(select file_save_locate from file_detail fd, file_group fg, tb_user us where fg.file_group_no =fd.file_group_no and fg.file_group_no =us.user_profile and u.user_no=us.user_no) profile, case when e.position_no = 1 then '사원' when e.position_no = 2 then '과장' when e.position_no = 3 then '부장' when e.position_no = 4 then 'CEO' end as positionNm, case when e.dept_no = 1 then '인사/행정' when e.dept_no = 2 then '경영' when e.dept_no = 3 then '재정' when e.dept_no = 4 then '전략/기획' when e.dept_no = 5 then '물류' end as deptNm from salary s, tb_user u, employee e where s.user_no=u.user_no and u.user_no=e.user_no
and u.user_nm like '%' || #{keyword} || '%'
AND e.dept_no=#{deptNo}
AND e.position_no=#{positionNo}
)t WHERE T.RNUM BETWEEN (#{currentPage} * 10) - (10 - 1) AND (#{currentPage} * 10)

select t.* from( select ROW_NUMBER() OVER(order by sal_pymnt_date desc) RNUM, s.*, e.store_no, e.position_no, u.user_nm,(select file_save_locate from file_detail fd, file_group fg, tb_user us where fg.file_group_no =fd.file_group_no and fg.file_group_no =us.user_profile and u.user_no=us.user_no) profile, case when e.position_no = 5 then '점주' when e.position_no = 6 then '알바' when e.position_no = 7 then '매니저' end as positionNm from salary s, tb_user u, store_emp e where s.user_no=u.user_no and u.user_no=e.user_no and e.store_no=#{storeNo}
and u.user_nm like '%' || #{keyword} || '%'
)t WHERE T.RNUM BETWEEN (#{currentPage} * 10) - (10 - 1) AND (#{currentPage} * 10)

select count(*)
from salary s, tb_user u, employee e
where s.user_no=u.user_no
and u.user_no=e.user_no

	and u.user_nm like '%' || #{keyword} || '%'


	AND e.dept_no=#{deptNo}


	AND extract(year from s.sal_pymnt_date)=#{year}


	AND extract(month from s.sal_pymnt_date)=#{month}

select e.*, u.user_nm, u.user_indate, u.user_phone, (select file_save_locate from file_detail fd, file_group fg, tb_user us where fg.file_group_no =fd.file_group_no and fg.file_group_no =us.user_profile and u.user_no=us.user_no) profile, (select position_nm from position p, employee e, tb_user us where p.position_no=e.position_no and e.user_no=us.user_no and u.user_no=us.user_no) positionNm, (select dept_nm from dept d, employee e, tb_user us where d.dept_no=e.dept_no and e.user_no=us.user_no and u.user_no=us.user_no) deptNm from employee e, tb_user u where e.user_no = u.user_no and e.position_no!=4 and e.position_no!=8
and position_no=#{positionNo}
and dept_no=#{deptNo}
